pub fn optExpr(self: *Cx, e: ?Expr) void {
            if (e) |val| {
                _ = &val;
                _ = self.expr(val);
            }
    }

pub fn stmt(self: *Cx, s: Stmt) void {
            switch (s.data) {
.s_block => |x| {
_ = self.stmtList((&x.stmts));
},
.s_class => |x| {
_ = self.class((&x.class));
},
.s_do_while => |x| {
_ = self.body((&x.body));
            _ = self.expr(x.test_);
},
.s_export_default => |x| {
switch ((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value)) {
.stmt => |st| {
_ = self.stmt(st);
},
.expr => |ex| {
_ = self.expr(ex);
},
}
},
.s_expr => |x| {
_ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
},
.s_for_in => |x| {
_ = self.stmt(x.init);
            _ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
            _ = self.body((&x.body));
},
.s_for_of => |x| {
_ = self.stmt(x.init);
            _ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
            _ = self.body((&x.body));
},
.s_for => |x| {
if (x.init) |*init| {
                _ = &init;
                _ = self.stmt((init.*));
            }
            _ = self.optExpr(x.test_);
            _ = self.optExpr(x.update);
            _ = self.body((&x.body));
},
.s_function => |x| {
_ = self.func((&x.func));
},
.s_if => |x| {
_ = self.expr(x.test_);
            _ = self.body((&x.yes));
            if ((x.no != null)) {
                _ = self.body((&x.no.?));
            }
},
.s_label => |x| {
_ = self.body((&x.stmt));
},
.s_local => |x| {
for (cp_iter_slice(x.decls.slice())) |d| {
                _ = &d;
                _ = self.binding(d.binding);
                _ = self.optExpr((if (@typeInfo(@TypeOf(d)) == .@"enum") @intFromEnum(d) else d.value));
            }
},
.s_return => |x| {
_ = self.optExpr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
},
.s_switch => |x| {
_ = self.expr(x.test_);
            for (cp_mut_slice(&x.cases)) |*c| {
                _ = &c;
                _ = self.optExpr((if (@typeInfo(@TypeOf((c.*))) == .@"enum") @intFromEnum((c.*)) else (c.*).value));
                _ = self.stmtList((&(c.*).body));
            }
},
.s_throw => |x| {
_ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
},
.s_try => |x| {
_ = self.stmtList((&x.body));
            if (x.catch_) |*c| {
                _ = &c;
                if ((c.*).binding) |b| {
                    _ = &b;
                    _ = self.binding(b);
                }
                _ = self.stmtList((&(c.*).body));
            }
            if (x.finally) |*f| {
                _ = &f;
                _ = self.stmtList((&(f.*).stmts));
            }
},
.s_while => |x| {
_ = self.expr(x.test_);
            _ = self.body((&x.body));
},
.s_with => |x| {
_ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
            _ = self.body((&x.body));
},
.s_import => |x| {
x.is_single_line = (x.items.len <= ONE_LINE_MAX);
},
.s_export_clause => |x| {
x.is_single_line = (x.items.len <= ONE_LINE_MAX);
},
.s_export_from => |x| {
x.is_single_line = (x.items.len <= ONE_LINE_MAX);
},
else => {

},
}
    }

pub fn expr(self: *Cx, e: Expr) void {
            switch (e.data) {
.e_array => |x| {
x.is_single_line = (x.items.len <= 8);
            for (cp_iter_slice(x.items.slice())) |item| {
                _ = &item;
                _ = self.expr(item);
            }
},
.e_unary => |x| {
_ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
},
.e_binary => |x| {
var work: std.ArrayListUnmanaged(Expr) = .{};
            _ = &work;
            defer {
            _ = work.deinit(self.allocator);
            }
            _ = (blk_catch_10: { break :blk_catch_10 ((work.append(self.allocator, x.left)) catch |__ce_10| { _ = &__ce_10; return; }); });
            _ = (blk_catch_11: { break :blk_catch_11 ((work.append(self.allocator, x.right)) catch |__ce_11| { _ = &__ce_11; return; }); });
            while ((work.items.len > 0)) {
                const cur = (work.pop()).?;
                if ((cur.data == .e_binary)) {
                    _ = (blk_catch_12: { break :blk_catch_12 ((work.append(self.allocator, cur.data.e_binary.left)) catch |__ce_12| { _ = &__ce_12; return; }); });
                    _ = (blk_catch_13: { break :blk_catch_13 ((work.append(self.allocator, cur.data.e_binary.right)) catch |__ce_13| { _ = &__ce_13; return; }); });
                } else {
                    _ = self.expr(cur);
                }
            }
},
.e_class => |c| {
_ = self.class(c);
},
.e_new => |x| {
_ = self.expr(x.target);
            for (cp_iter_slice(x.args.slice())) |a| {
                _ = &a;
                _ = self.expr(a);
            }
},
.e_function => |f| {
_ = self.func((&f.func));
},
.e_call => |x| {
_ = self.expr(x.target);
            for (cp_iter_slice(x.args.slice())) |a| {
                _ = &a;
                _ = self.expr(a);
            }
},
.e_dot => |x| {
_ = self.expr(x.target);
},
.e_index => |x| {
_ = self.expr(x.target);
            _ = self.expr(x.index);
},
.e_arrow => |x| {
for (cp_mut_slice(&x.args)) |*arg| {
                _ = &arg;
                _ = self.binding((arg.*).binding);
                _ = self.optExpr((arg.*).default);
            }
            _ = self.stmtList((&x.body.stmts));
},
.e_object => |x| {
x.is_single_line = (x.properties.len <= ONE_LINE_MAX);
            for (cp_iter_slice(x.properties.slice())) |p| {
                _ = &p;
                _ = self.optExpr(p.key);
                _ = self.optExpr((if (@typeInfo(@TypeOf(p)) == .@"enum") @intFromEnum(p) else p.value));
                _ = self.optExpr(p.initializer);
            }
},
.e_jsx_element => |x| {
_ = self.optExpr(x.tag);
            for (cp_iter_slice(x.properties.slice())) |p| {
                _ = &p;
                _ = self.optExpr(p.key);
                _ = self.optExpr((if (@typeInfo(@TypeOf(p)) == .@"enum") @intFromEnum(p) else p.value));
                _ = self.optExpr(p.initializer);
            }
            for (cp_iter_slice(x.children.slice())) |c| {
                _ = &c;
                _ = self.expr(c);
            }
},
.e_spread => |x| {
_ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
},
.e_template => |x| {
_ = self.optExpr(x.tag);
            for (cp_iter_slice(x.parts)) |part| {
                _ = &part;
                _ = self.expr((if (@typeInfo(@TypeOf(part)) == .@"enum") @intFromEnum(part) else part.value));
            }
},
.e_import => |x| {
_ = self.expr(x.expr);
            _ = self.optExpr(x.options);
},
.e_await => |x| {
_ = self.expr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
},
.e_yield => |x| {
_ = self.optExpr((if (@typeInfo(@TypeOf(x)) == .@"enum") @intFromEnum(x) else x.value));
},
.e_if => |x| {
_ = self.expr(x.test_);
            _ = self.expr(x.yes);
            _ = self.expr(x.no);
},
else => {

},
}
    }
};

const StmtSlice = []Stmt;
