pub fn relayout(allocator: std.mem.Allocator, ast: *js_ast.Ast, split: bool) void {
        var cx = Cx{ .allocator = allocator, .split = split };
        _ = &cx;
        for (cp_mut_slice(&ast.parts.slice())) |*part| {
            _ = &part;
            _ = cx.stmtList((&(part.*).stmts));
        }
}
